#include <iostream>
#include <fstream>
#include <string>

// Function to count the occurrence of a word in a text file
int countOccurrences(string word, ifstream& fin) 
{ 
    int count = 0; 
    while (true) 
    { 
        string line; 
        getline(fin, line); 
        if (line.find(word) != string::npos) 
            count++; 
    } 
    return count; 
} 

// Driver code 
// Output should be 3 
int main() 
{ 
    ifstream fin("file.txt"); 
    string word = "bank"; 
    int count = countOccurrences(word, fin); 
    cout << "Number of occurrences of the word \"" << word << "\" in the text file is " << count; 
    return 0; 
}

