#include <string>

using namespace std; 

int countOccurrences(string line, const string word) 
{ 
    int count = 0; 

    // Split the line by whitespace 
    istringstream iss(line); 
    string word_found; 
    while (iss >> word_found) 
    { 
        if(word_found == word) 
            count++; 
    } 

    return count; 
}

// Driver code 

