This is a second line with the word 'banana' only 
The third line has no words 
"; 

// Output: 
int main() 
{ 
    string line;
    ifstream myfile("input.txt"); 

    // Count the occurrence of 'apple' 
    int count = countOccurrences(line, "apple"); 

    // Print the output 
