import re

def validate_email(email_string):
    email_regex = r'^[\w\.-]+@[\w\.-]+$'
    m = re.match(email_regex, email_string)
    if m:
        return m.group()
    else:
        return None

if __name__ == '__main__':
    email_string = 'example@example.com'
    print(validate_email(email_string))
    # Output: example@example.com (valid email address)

