            self.front = item
        else:
            self.back = item

    def dequeue(self):
        if self.front is not None:
            item = self.front
            self.front = self.front.next
            return item

    # Returns the number of items in the queue
    def size(self):
        if self.front is not None:
            return len(self.front.next) + 1
        else:
            return 0

