def findCommonElements(arr1, arr2): 
  # Create two empty dictionaries 
  res1 = {} 
  res2 = {} 

  # Iterate over the elements of the two arrays 
  for i in range(len(arr1)): 
    if arr1[i] in res1: 
      res2[i] = arr2[i] 
    else: 
      res1[i] = arr1[i] 

  # Return the common elements 
  return res1.items() & res2.items()

