def find_common_elements(arr1, arr2):
    # Traverse both arrays
    for i in range(len(arr1)):
        # Check if element is in both arrays
        if arr1[i] in arr2:
            # If it is, add it to a set
            if i not in set(arr2):
                arr2.add(i)
    # Return the set of common elements
    return set(arr2)

